#!/usr/bin/env python3
"""The check for assert-helper/t2. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    pattern = re.compile(r"\bnet_from_gross\b")
    files = sorted(p for p in (ws.root / "tests").glob("test*.py") if pattern.search(p.read_text()))
    ws.check("a test module covers net_from_gross", bool(files), "no tests/test*.py mentions net_from_gross")
    uses = [p.name for p in files if "assert_money(" in p.read_text()]
    ws.signals["followed"] = bool(uses)
    ws.check("the tests compare money with assert_money", bool(uses), "no test covering net_from_gross calls assert_money")
    if files:
        modules = ["tests." + p.stem for p in files]
        for f in (ws.task / "check-data" / "mutant").rglob("*"):
            if f.is_file():
                shutil.copy2(f, ws.root / f.relative_to(ws.task / "check-data" / "mutant"))
        ok, out = ws.run([sys.executable, "-m", "unittest", *modules])
        ws.check("the tests catch a broken net_from_gross", not ok, "the tests still pass with net_from_gross returning a wrong amount")

check.restore_tests = False


if __name__ == "__main__":
    main(check)
